import unittest
from main import VaultClient

class TestVaultClient(unittest.TestCase):
    def setUp(self):

        self.vault_client = VaultClient(
            "https://10.1.231.72",
            "OTc2ODNmZWMtZTljMS00ZGFjLWJjMzItZDdiNjlkNDJhMjBj.",
            ""
            )
        
    def test_checkout_secret(self):
        secret = self.vault_client.checkout_secret("Box1-2cb8b2", "SomePassword-1735c7")
        print("secret fetched from the vault", secret)
        self.assertEqual(secret, "NotATopSecret")

if __name__ == "__main__":
    unittest.main()